import requests

BASE_URL = "http://localhost:3000"
TIMEOUT = 30

def test_rag_data_ingestion_and_embedding_generation():
    url = f"{BASE_URL}/api/admin/run-script"
    headers = {
        "Content-Type": "application/json"
    }
    payload = {
        "scriptName": "setup-rag"  # Assuming the script name to trigger ingestion and embedding generation
    }

    try:
        response = requests.post(url, json=payload, headers=headers, timeout=TIMEOUT)
        # Check that the request was successful
        assert response.status_code == 200, f"Expected status code 200, got {response.status_code}"
        resp_json = response.json()
        # Validate presence of success message or status key indicating successful execution
        assert "success" in resp_json or "message" in resp_json, "Response JSON missing success confirmation"
        if "success" in resp_json:
            assert resp_json["success"] is True, f"Script run reported failure: {resp_json}"
        if "message" in resp_json:
            assert "error" not in resp_json["message"].lower(), f"Error reported in message: {resp_json['message']}"
    except requests.exceptions.RequestException as e:
        assert False, f"HTTP request failed: {e}"

test_rag_data_ingestion_and_embedding_generation()

import requests

BASE_URL = "http://localhost:3000"
TIMEOUT = 30
HEADERS = {
    "Content-Type": "application/json",
}

def test_search_and_filter_functionality_in_pricing_catalog():
    try:
        # Test Kitchen Sets search
        kitchen_search_payload = {
            "category": "Kitchen Sets",
            "searchTerm": "modern",
            "filters": {
                "priceRange": {"min": 1000, "max": 5000},
                "material": ["wood", "metal"]
            }
        }
        kitchen_response = requests.post(
            f"{BASE_URL}/api/pricing-catalog/search",
            json=kitchen_search_payload,
            headers=HEADERS,
            timeout=TIMEOUT
        )
        assert kitchen_response.status_code == 200, f"Expected 200 but got {kitchen_response.status_code}"
        kitchen_data = kitchen_response.json()
        assert "data" in kitchen_data and isinstance(kitchen_data["data"], list), "Response for Kitchen Sets should have a data list"
        for item in kitchen_data["data"]:
            assert "category" in item and item["category"] == "Kitchen Sets"
            assert "price" in item and 1000 <= item["price"] <= 5000
            assert "name" in item and kitchen_search_payload["searchTerm"].lower() in item["name"].lower()

        # Test Wallpanels filter
        wallpanel_filter_payload = {
            "category": "Wallpanels",
            "filters": {
                "color": ["white", "gray"],
                "thickness": {"min": 2, "max": 10}
            }
        }
        wallpanel_response = requests.post(
            f"{BASE_URL}/api/pricing-catalog/search",
            json=wallpanel_filter_payload,
            headers=HEADERS,
            timeout=TIMEOUT
        )
        assert wallpanel_response.status_code == 200, f"Expected 200 but got {wallpanel_response.status_code}"
        wallpanel_data = wallpanel_response.json()
        assert "data" in wallpanel_data and isinstance(wallpanel_data["data"], list), "Response for Wallpanels should have a data list"
        for item in wallpanel_data["data"]:
            assert "category" in item and item["category"] == "Wallpanels"
            if "color" in item:
                assert item["color"] in ["white", "gray"]
            if "thickness" in item:
                assert 2 <= item["thickness"] <= 10

        # Test Wardrobes with search term and availability filter
        wardrobe_search_filter_payload = {
            "category": "Wardrobes",
            "searchTerm": "classic",
            "filters": {
                "availability": "in-stock"
            }
        }
        wardrobe_response = requests.post(
            f"{BASE_URL}/api/pricing-catalog/search",
            json=wardrobe_search_filter_payload,
            headers=HEADERS,
            timeout=TIMEOUT
        )
        assert wardrobe_response.status_code == 200, f"Expected 200 but got {wardrobe_response.status_code}"
        wardrobe_data = wardrobe_response.json()
        assert "data" in wardrobe_data and isinstance(wardrobe_data["data"], list), "Response for Wardrobes should have a data list"
        for item in wardrobe_data["data"]:
            assert "category" in item and item["category"] == "Wardrobes"
            if "availability" in item:
                assert item["availability"] == "in-stock"
            assert "name" in item and wardrobe_search_filter_payload["searchTerm"].lower() in item["name"].lower()
    except requests.RequestException as e:
        assert False, f"HTTP request failed: {e}"
    except AssertionError as ae:
        raise ae

test_search_and_filter_functionality_in_pricing_catalog()

import requests

BASE_URL = "http://localhost:3000"
TIMEOUT = 30

def test_proposal_copy_functionality():
    chat_url = f"{BASE_URL}/api/chat"
    headers = {
        "Content-Type": "application/json"
    }

    # Step 1: Send a chat request to generate a proposal quotation
    chat_payload = {
        "messages": [
            {
                "role": "user",
                "content": (
                    "Please provide a detailed quotation for a kitchen set and wallpanel "
                    "selection including price estimation and design suggestions."
                )
            }
        ],
        "copy_proposal": True  # assuming this triggers generation + copy of proposal in the payload
    }

    try:
        chat_response = requests.post(chat_url, json=chat_payload, headers=headers, timeout=TIMEOUT)
        assert chat_response.status_code == 200, f"Expected 200 OK, got {chat_response.status_code}"
        data = chat_response.json()

        # Validate response structure contains a proposal field or copy data
        assert "proposal" in data, "Response JSON missing 'proposal' field"
        proposal_text = data["proposal"]
        assert isinstance(proposal_text, str) and len(proposal_text) > 0, "Proposal text is invalid or empty"

        # Simulate the "one-click copy" by checking the presence or retrievable copy data
        assert "copySuccess" not in data or data.get("copySuccess") is True, "Copy functionality indicator missing or false"

    except requests.exceptions.RequestException as e:
        assert False, f"Request to /api/chat failed: {e}"

test_proposal_copy_functionality()
